import{_ as t,o,c as r,a2 as s}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Azure Resource Graph round-trips per run","description":"","frontmatter":{},"headers":[],"relativePath":"design/arg-round-trips.md","filePath":"design/arg-round-trips.md"}'),a={name:"design/arg-round-trips.md"};function d(n,e,c,i,l,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="azure-resource-graph-round-trips-per-run" tabindex="-1">Azure Resource Graph round-trips per run <a class="header-anchor" href="#azure-resource-graph-round-trips-per-run" aria-label="Permalink to &quot;Azure Resource Graph round-trips per run&quot;">​</a></h1><p>Tracks ADO AB#5648 (Epic AB#5638).</p><div class="warning custom-block"><p class="custom-block-title">Partly stale — written mid-rewrite, <code>Modules/</code> is now deleted</p><p>This document was written during the AB#5648 inversion, while the collector tree still had a live <code>Modules/Private/...</code> shim layer alongside the new <code>src/collect/</code> functions. As of v3.0.0 that shim layer — every <code>Modules/Private/...</code> path named below — <strong>no longer exists in the repository</strong>; the retired collector-script tree and imperative fallback were deleted outright (see <a href="./../project/changelog.html"><code>docs/changelog.md</code></a> v3.0.0, and <a href="./../project/ari-differences.html#engine-rewrite-ari-shipped-none-of-this"><code>docs/ari-differences.md</code></a>). The query counts and call-site <em>purposes</em> below are still the right mental model — the <code>src/collect/</code> half of every row is current — but any <code>Modules/Private/...</code> path is historical, not a file you can open today. <strong><code>src/ingest/Invoke-ArgQueryPack.ps1</code>, listed as a call site below, was also deleted</strong> — AB#6774 (2026-07-31) retired it outright once its six queries were confirmed to duplicate data <code>Invoke-Collect</code> already collects. Treat this page as an explanation of <em>why</em> the numbers are what they are, not as a current file map.</p></div><p>This is the map of <strong>every</strong> Azure Resource Graph and ARM REST call the product issues, where it is issued from, and what changed when <code>src/collect</code> became the single source of the raw data. It was derived by reading each call site, not from an earlier estimate.</p><p>A &quot;round-trip&quot; here means one <code>Search-AzGraph</code> invocation for one query and one subscription batch — not one page. Paging multiplies each entry by however many 1000-row pages the estate needs.</p><h2 id="where-resource-graph-is-reached-from" tabindex="-1">Where Resource Graph is reached from <a class="header-anchor" href="#where-resource-graph-is-reached-from" aria-label="Permalink to &quot;Where Resource Graph is reached from&quot;">​</a></h2><p>Every <code>Search-AzGraph</code> call site in the shipped module:</p><table tabindex="0"><thead><tr><th>Call site</th><th>Purpose</th><th>Queries issued</th></tr></thead><tbody><tr><td><code>src/collect/Get-ScoutRawInventory.ps1</code></td><td>the single raw pass</td><td>3 tables always; up to 6 more behind <code>-Include*</code> switches</td></tr><tr><td><code>src/collect/Get-ScoutGovernanceDataset.ps1</code></td><td>governance, collected once for both consumers (AB#6779)</td><td>2 always (<code>authorizationresources</code>, <code>policyresources</code>), issued from the raw pass</td></tr><tr><td><code>src/collect/Invoke-Collect.ps1</code></td><td>typed assessment pack</td><td>1 (<code>sqlDefenderPricing</code>) by default; 35 under <code>-Source TypedQueries</code></td></tr><tr><td><code>Modules/Private/Extraction/Get-AZTIManagementGroups.ps1</code></td><td>expand a management group into its subscriptions</td><td>1, only when <code>-ManagementGroup</code> is supplied</td></tr><tr><td><code>manifests/collectors/Management/AllSubscriptions.ps1</code></td><td>one inventory collector&#39;s own lookup</td><td>1, during processing</td></tr><tr><td><code>src/ingest/Import-Governance.ps1</code></td><td>governance ingestor</td><td>1 (management groups), only for assessments whose manifest lists <code>Ingest = &#39;Governance&#39;</code>. Was 3; the other two moved to <code>Get-ScoutGovernanceDataset</code> (AB#6779) and are skipped here when the collect pass supplies them</td></tr><tr><td><s><code>src/ingest/Invoke-ArgQueryPack.ps1</code></s></td><td><em>(deleted, AB#6774)</em> — opt-in ARG query pack ingestor</td><td>All six of its queries duplicated data <code>Invoke-Collect</code> already collected, and it overwrote the collector&#39;s results with <code>Add-Member -Force</code>. A manifest that still names the ingest is ignored with a verbose line rather than erroring</td></tr><tr><td><code>scripts/Export-ScoutFixture.ps1</code></td><td>developer fixture capture</td><td>not part of a product run</td></tr></tbody></table><p><code>Modules/Private/Extraction/Start-AZTIGraphExtraction.ps1</code> and <code>Modules/Private/Extraction/Invoke-AZTIInventoryLoop.ps1</code> <strong>used to</strong> be call sites. The first is now a parameter-translation shim with no query text and no ARG call; the second is deleted.</p><h2 id="before-and-after" tabindex="-1">Before and after <a class="header-anchor" href="#before-and-after" aria-label="Permalink to &quot;Before and after&quot;">​</a></h2><p>Measured with a counting stub in place of <code>Search-AzGraph</code>, and pinned by <code>tests/Collect.SinglePassInversion.Tests.ps1</code>.</p><table tabindex="0"><thead><tr><th>Entry point</th><th>v2.7.0</th><th>after AB#5648</th></tr></thead><tbody><tr><td>Assessment-only collect (<code>Invoke-AzureScout -Assessment</code>, default)</td><td><strong>35</strong></td><td><strong>4</strong></td></tr><tr><td>Assessment collect, <code>-Source TypedQueries</code> (opt-in)</td><td>35</td><td>35</td></tr><tr><td>Assessment collect, <code>-FromInventory</code> (combined run)</td><td>1</td><td>1</td></tr><tr><td>Inventory extraction (<code>Invoke-AzureScout</code>, default switches)</td><td>8</td><td>8</td></tr><tr><td>Combined inventory + assessment, end to end</td><td>9</td><td>9</td></tr></tbody></table><p>Excluded from those numbers because they are conditional on flags or manifest entries, and unchanged by this work: the management-group expansion (1, only with <code>-ManagementGroup</code>), the <code>AllSubscriptions</code> collector (1, during processing), and the two ingestors.</p><h3 id="governance-ab-6779" tabindex="-1">Governance (AB#6779) <a class="header-anchor" href="#governance-ab-6779" aria-label="Permalink to &quot;Governance (AB#6779)&quot;">​</a></h3><p>Rendering role assignments, policy assignments, resource locks and budgets as worksheets added no round trip. It moved two of them:</p><table tabindex="0"><thead><tr><th></th><th>before AB#6779</th><th>after</th></tr></thead><tbody><tr><td><code>Get-ScoutGovernanceDataset</code>, inside the raw pass</td><td>—</td><td>2 ARG + 2 ARM REST per subscription</td></tr><tr><td><code>Import-Governance</code>, on a run the collect pass fed</td><td>3 ARG + 2 ARM REST per subscription</td><td>1 ARG, 0 REST</td></tr><tr><td><strong>Total, assessment run</strong></td><td><strong>3 ARG + 2/sub REST</strong></td><td><strong>3 ARG + 2/sub REST</strong></td></tr></tbody></table><p>The inventory-only run does pay the 2 ARG + 2/sub REST it did not pay before, because it did not previously collect governance at all — that is the cost of the four worksheets existing, and it is the only place the number moves. Both sides are counted in <code>tests/Collect.Governance.Tests.ps1</code>.</p><h2 id="why-the-inventory-number-is-8-and-not-1" tabindex="-1">Why the inventory number is 8 and not 1 <a class="header-anchor" href="#why-the-inventory-number-is-8-and-not-1" aria-label="Permalink to &quot;Why the inventory number is 8 and not 1&quot;">​</a></h2><p>The inventory extraction reads eight <strong>distinct</strong> Resource Graph tables. They are not different filters over one table, so they cannot be merged into one query without dropping datasets:</p><p><code>resourcecontainers</code>, <code>resources</code>, <code>networkresources</code>, <code>SupportResources</code>, <code>recoveryservicesresources</code>, <code>desktopvirtualizationresources</code>, <code>advisorresources</code>, plus the file-backed retirement query. <code>securityresources</code> makes a ninth when <code>-SecurityCenter</code> is supplied.</p><p>What changed is not the count but the ownership: all eight are now issued by one function, with one paging implementation (<code>SkipToken</code>), one batching rule (1000 subscriptions per call), one throttle-retry policy and one per-batch error-isolation policy. Before, there were two independent implementations of that machinery and 43 round-trips across a combined run&#39;s two passes over the same resource types.</p><h2 id="the-two-documented-exceptions-to-one-pass" tabindex="-1">The two documented exceptions to &quot;one pass&quot; <a class="header-anchor" href="#the-two-documented-exceptions-to-one-pass" aria-label="Permalink to &quot;The two documented exceptions to &quot;one pass&quot;&quot;">​</a></h2><p>Both are real, both are asserted in the test file rather than hidden:</p><ol><li><strong><code>sqlDefenderPricing</code></strong> reads the <code>SecurityResources</code> table (<code>microsoft.security/pricings</code>). No inventory pass collects it: the inventory <code>securityresources</code> query filters to <code>microsoft.security/assessments</code> with an <code>Unhealthy</code> status, which cannot contain a pricings row. It stays a live typed query, so a default assessment collect is 3 + 1, not 3.</li><li><strong><code>Retirements</code></strong> is a file-backed KQL query (<code>src/report/renderers/inventory/style/Retirement.kql</code>) with its own joins over service-health data. It is not derivable from the raw row set either. It moved into <code>Get-ScoutRawInventory -IncludeRetirements</code> so it is issued from the same place as everything else, but it is still its own round-trip.</li></ol><h2 id="the-trade-off-stated-plainly" tabindex="-1">The trade-off, stated plainly <a class="header-anchor" href="#the-trade-off-stated-plainly" aria-label="Permalink to &quot;The trade-off, stated plainly&quot;">​</a></h2><p>The round-trip <strong>count</strong> dropped from 35 to 4 for an assessment collect. The raw pass transfers the full <code>properties</code> bag for every resource in scope, where the typed queries transferred narrow projections — so on a large estate the number of 1000-row <strong>pages</strong> can go up even as the number of queries goes down. <code>-Categories</code> no longer reduces what is <em>fetched</em> (it still filters what is shaped and returned).</p><p>This is the same trade the combined-run <code>-FromInventory</code> path has made since v2.5.0. <code>-Source TypedQueries</code> remains available for a narrow single-category collect where projection size matters more than call count.</p><p><strong>Unverified:</strong> the page-count effect has not been measured against a large live estate. The numbers in this document are query counts from a mocked run, not page counts or wall-clock time.</p><h2 id="non-arg-data-sources" tabindex="-1">Non-ARG data sources <a class="header-anchor" href="#non-arg-data-sources" aria-label="Permalink to &quot;Non-ARG data sources&quot;">​</a></h2><p>Not Resource Graph. Every one of these is a control-plane or data-plane call with <strong>no Resource Graph table at all</strong> — they are not resources, they are point-in-time computed data — so none of them can be folded into <code>Get-ScoutRawInventory</code> no matter how the raw row set is shaped.</p><p>As of the second half of AB#5648 all four run from <code>src/collect</code>. The <code>Modules/Private</code> files are parameter-translation shims that issue no Azure call of their own.</p><table tabindex="0"><thead><tr><th>Source</th><th>Cmdlet / endpoint</th><th>Implementation (live)</th><th>Shim</th></tr></thead><tbody><tr><td>ARM REST — resource health, managed identities, advisor score, reservation recommendations, policy</td><td><code>Invoke-RestMethod</code> over 7 ARM endpoints</td><td><code>src/collect/Get-ScoutApiResources.ps1</code></td><td><code>Modules/Private/Extraction/Get-AZTIAPIResources.ps1</code></td></tr><tr><td>VM quotas</td><td><code>Get-AzVMUsage</code></td><td><code>src/collect/Get-ScoutVmQuotas.ps1</code></td><td><code>.../ResourceDetails/Get-AZTIVMQuotas.ps1</code></td></tr><tr><td>VM SKU details</td><td><code>Get-AzComputeResourceSku</code></td><td><code>src/collect/Get-ScoutVmSkuDetails.ps1</code></td><td><code>.../ResourceDetails/Get-AZTIVMSkuDetails.ps1</code></td></tr><tr><td>Cost Management</td><td><code>Invoke-AzCostManagementQuery</code></td><td><code>src/collect/Get-ScoutCostInventory.ps1</code></td><td><code>Modules/Private/Extraction/Get-AZTICostInventory.ps1</code></td></tr></tbody></table><h3 id="call-counts-per-default-inventory-run" tabindex="-1">Call counts per default inventory run <a class="header-anchor" href="#call-counts-per-default-inventory-run" aria-label="Permalink to &quot;Call counts per default inventory run&quot;">​</a></h3><p>None of these are Resource Graph round-trips, so they do not appear in the table above. They are listed here because they are the rest of the answer to &quot;how many times do we call Azure&quot;, and on a large tenant they dominate it — the ARM REST pull alone is <strong>7 sequential calls per subscription</strong> with 200ms of deliberate pacing between them.</p><table tabindex="0"><thead><tr><th>Source</th><th>Calls</th><th>Scope</th><th>Gated by</th></tr></thead><tbody><tr><td>ARM REST</td><td>7 × subscriptions (4 × when <code>-SkipPolicy</code>)</td><td>per subscription</td><td><code>-SkipAPIs</code></td></tr><tr><td>VM quotas</td><td>1 × (subscription, location) pairs that actually contain a VM or VMSS</td><td>per subscription <strong>and</strong> region</td><td><code>-SkipVMDetails</code></td></tr><tr><td>VM SKU details</td><td>1 × distinct locations that actually contain a VM or VMSS</td><td>per region</td><td><code>-SkipVMDetails</code></td></tr><tr><td>Cost Management</td><td>1 × subscriptions</td><td>per subscription</td><td><code>-IncludeCosts</code> (off by default)</td></tr></tbody></table><p>The quota and SKU calls are targeted rather than exhaustive: only regions the tenant actually deploys into are queried, which is the v1 behaviour and is preserved.</p><p><code>tests/Collect.NonArgInversion.Tests.ps1</code> pins this two ways — an AST assertion that no file under <code>Modules/</code> calls any of these five cmdlets any more, and an equivalence comparison against the retired v1 implementations (reproduced verbatim in that file) over identical stubbed Azure responses, compared key by key.</p><h3 id="deliberate-behaviour-changes" tabindex="-1">Deliberate behaviour changes <a class="header-anchor" href="#deliberate-behaviour-changes" aria-label="Permalink to &quot;Deliberate behaviour changes&quot;">​</a></h3><p>Three, all in the direction of &quot;one optional dataset failing must not destroy its neighbours&quot;, which is the AB#5636 defect class:</p><ol><li>A failed <code>policyStates/summarize</code> call no longer discards the two Policy <strong>definition</strong> lists. v1 wrapped all three in one <code>try</code>, so a denial on the first — the one most often denied — threw away two lists that were never attempted.</li><li>A <code>Get-AzVMUsage</code> failure for one (subscription, region) pair skips that pair instead of terminating the whole quota pass. Likewise <code>Get-AzComputeResourceSku</code> per region.</li><li>A VM row with no location no longer produces an empty-string region lookup.</li></ol><p>Two shapes were deliberately <strong>kept</strong> rather than &quot;improved&quot;, because a consumer depends on them:</p><ul><li><code>CostData</code> is not wrapped in <code>@()</code>. <code>Get-ScoutCostAnomaly</code> reads the raw shape with <code>$item.CostData.PSObject.Properties[&#39;Row&#39;]</code>, which is <code>$null</code> on an array — wrapping it produced zero anomaly records with no error.</li><li>The API-resource result elements stay <strong>hashtables</strong> with the v1 key names (<code>ReservationRecomen</code>, <code>PolicyAssign</code>, <code>PolicyDef</code>, <code>PolicySetDef</code>), because <code>Start-AZSCExtractionOrchestration</code> reads them by string through <code>Get-AZSCCollectedValue</code>&#39;s <code>IDictionary</code> branch.</li></ul><h3 id="still-standing-and-why" tabindex="-1">Still standing, and why <a class="header-anchor" href="#still-standing-and-why" aria-label="Permalink to &quot;Still standing, and why&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Verdict</th></tr></thead><tbody><tr><td><code>Get-AZTIManagementGroups.ps1</code></td><td><strong>Left standing.</strong> It issues one ARG query, only when <code>-ManagementGroup</code> is supplied, to expand a management group into its subscriptions. It runs <em>before</em> collection to decide the subscription scope, so it cannot be served from a pass that has not happened yet. Folding it into <code>Get-ScoutRawInventory</code> would mean two passes, which is the thing this epic is removing.</td></tr><tr><td><code>Get-AZTISubscriptions.ps1</code></td><td><strong>Left standing.</strong> Wraps <code>Get-AzSubscription</code>/<code>Get-AzContext</code>; no Resource Graph, no duplication.</td></tr><tr><td><code>Start-AZTIEntraExtraction.ps1</code></td><td><strong>Left standing.</strong> Microsoft Graph, not ARM. Different service, different token audience, nothing in <code>src/collect</code> covers it.</td></tr><tr><td><code>Start-AZTIDevOpsExtraction.ps1</code></td><td><strong>Left standing.</strong> <code>dev.azure.com</code> REST, not ARM. Same reasoning.</td></tr></tbody></table><p>After this work exactly two files under <code>Modules/</code> still call <code>Invoke-RestMethod</code>: <code>Start-AZTIDevOpsExtraction.ps1</code> (Azure DevOps) and <code>Modules/Private/Main/Invoke-AZTIGraphRequest.ps1</code> (Microsoft Graph, which is what the Entra extraction goes through). Both are named individually in the AST test&#39;s allow-list rather than excluded by directory, so a third one cannot appear unnoticed.</p>',45)])])}const m=t(a,[["render",d]]);export{p as __pageData,m as default};
